 17→//! JSON-RPC protocol definitions for system adapter communication.
 18→//!
 19→//! This crate defines the request/response types for the system adapter
 20→//! JSON-RPC protocol, which allows spicebench to communicate with external
 21→//! benchmark execution environments.
 22→//!
 23→//! # Features
 24→//!
 25→//! - **Protocol types**: Request/response types for setup, teardown, and metrics
 26→//! - **Client**: Ready-to-use client with Stdio and HTTP transports (requires `client` feature)
 27→//! - **Server**: Easy server implementation via Handler trait (requires `server` feature)
 28→//! - **JSON-RPC**: Standard JSON-RPC 2.0 envelope types
 29→//!
 30→//! # Client Example
 31→//!
 32→//! ```no_run
 33→//! # #[cfg(feature = "client")]
 34→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 35→//! use system_adapter_protocol::Client;
 36→//! use std::collections::HashMap;
 37→//! use uuid::Uuid;
 38→//!
 39→//! // Create an HTTP client
 40→//! let mut client = Client::http("http://localhost:8080");
 41→//!
 42→//! // Setup a benchmark run
 43→//! let run_id = Uuid::new_v4();
 44→//! let setup_response = client.setup(run_id, HashMap::new(), HashMap::new()).await?;
 45→//!
 46→//! println!("Driver: {:?}", setup_response.driver);
 47→//!
 48→//! // Teardown the run
 49→//! let teardown_response = client.teardown(run_id).await?;
 50→//! # Ok(())
 51→//! # }
 52→//! ```
 53→//!
 54→//! # Server Example
 55→//!
 56→//! ```no_run
 57→//! # #[cfg(feature = "server")]
 58→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 59→//! use system_adapter_protocol::{
 60→//!     AdbcDriver, DatasetConfig, Handler, Server, SetupResponse, TeardownResponse,
 61→//! };
 62→//! use async_trait::async_trait;
 63→//! use std::collections::HashMap;
 64→//! use uuid::Uuid;
 65→//!
 66→//! struct MyHandler;
 67→//!
 68→//! #[async_trait]
 69→//! impl Handler for MyHandler {
 70→//!     async fn setup(
 71→//!         &mut self,
 72→//!         run_id: Uuid,
 73→//!         metadata: HashMap<String, serde_json::Value>,
 74→//!         datasets: HashMap<String, DatasetConfig>,
 75→//!     ) -> Result<SetupResponse, String> {
 76→//!         let _ = (metadata, datasets);
 77→//!         Ok(SetupResponse {
 78→//!             driver: AdbcDriver::Flightsql,
 79→//!             db_kwargs: HashMap::new(),
 80→//!         })
 81→//!     }
 82→//!
 83→//!     async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
 84→//!         Ok(TeardownResponse { ok: true })
 85→//!     }
 86→//! }
 87→//!
 88→//! // Run the server on stdio
 89→//! let mut server = Server::new(MyHandler);
 90→//! server.run_stdio().await?;
 91→//! # Ok(())
 92→//! # }
 93→//! ```
