112→/// ADBC driver types supported by the system adapter
113→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
114→#[serde(rename_all = "snake_case")]
115→pub enum AdbcDriver {
116→    #[serde(rename = "flightsql")]
117→    Flightsql,
118→    #[serde(rename = "databricks")]
119→    Databricks,
120→}
121→
122→impl std::fmt::Display for AdbcDriver {
123→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
124→        match self {
125→            Self::Flightsql => write!(f, "flightsql"),
126→            Self::Databricks => write!(f, "databricks"),
127→        }
128→    }
129→}
