138→/// Request to setup a benchmark run.
139→///
140→/// JSON-RPC method: `setup`
141→#[derive(Debug, Clone, Serialize, Deserialize)]
142→#[serde(deny_unknown_fields)]
143→pub struct SetupRequest {
144→    /// Unique identifier for this benchmark run
145→    pub run_id: Uuid,
146→    /// Arbitrary run metadata propagated from spicebench to adapters
147→    #[serde(default)]
148→    pub metadata: HashMap<String, serde_json::Value>,
149→    /// Map of dataset name to dataset definition
150→    pub datasets: HashMap<String, DatasetConfig>,
151→}
