235→/// Standard JSON-RPC 2.0 request envelope
236→#[derive(Debug, Clone, Serialize, Deserialize)]
237→pub struct JsonRpcRequest<T> {
238→    pub jsonrpc: String,
239→    pub id: serde_json::Value,
240→    pub method: String,
241→    pub params: T,
242→}
243→
244→impl<T> JsonRpcRequest<T> {
245→    /// Create a new JSON-RPC 2.0 request
246→    pub fn new(id: impl Into<serde_json::Value>, method: impl Into<String>, params: T) -> Self {
247→        Self {
248→            jsonrpc: "2.0".to_string(),
249→            id: id.into(),
250→            method: method.into(),
251→            params,
252→        }
253→    }
254→}
255→
256→/// Standard JSON-RPC 2.0 response envelope
257→#[derive(Debug, Clone, Serialize, Deserialize)]
258→pub struct JsonRpcResponse<T> {
259→    pub jsonrpc: String,
260→    pub id: serde_json::Value,
261→    #[serde(skip_serializing_if = "Option::is_none")]
262→    pub result: Option<T>,
263→    #[serde(skip_serializing_if = "Option::is_none")]
264→    pub error: Option<JsonRpcError>,
265→}
266→
267→impl<T> JsonRpcResponse<T> {
268→    /// Create a successful response
269→    pub fn success(id: impl Into<serde_json::Value>, result: T) -> Self {
270→        Self {
271→            jsonrpc: "2.0".to_string(),
272→            id: id.into(),
273→            result: Some(result),
274→            error: None,
275→        }
276→    }
277→
278→    /// Create an error response
279→    pub fn error(id: impl Into<serde_json::Value>, error: JsonRpcError) -> Self {
280→        Self {
281→            jsonrpc: "2.0".to_string(),
282→            id: id.into(),
283→            result: None,
284→            error: Some(error),
285→        }
286→    }
287→}
288→
289→/// JSON-RPC 2.0 error object
290→#[derive(Debug, Clone, Serialize, Deserialize)]
291→pub struct JsonRpcError {
292→    pub code: i32,
293→    pub message: String,
294→    #[serde(skip_serializing_if = "Option::is_none")]
295→    pub data: Option<serde_json::Value>,
296→}
297→
298→impl JsonRpcError {
299→    /// Create a new error
300→    pub fn new(code: i32, message: impl Into<String>) -> Self {
301→        Self {
302→            code,
303→            message: message.into(),
304→            data: None,
305→        }
306→    }
307→
308→    /// Create an error with additional data
309→    pub fn with_data(
310→        code: i32,
311→        message: impl Into<String>,
312→        data: impl Into<serde_json::Value>,
313→    ) -> Self {
314→        Self {
315→            code,
316→            message: message.into(),
317→            data: Some(data.into()),
318→        }
319→    }
320→}
321→
322→/// Standard JSON-RPC error codes
323→pub mod error_codes {
324→    pub const PARSE_ERROR: i32 = -32700;
325→    pub const INVALID_REQUEST: i32 = -32600;
326→    pub const METHOD_NOT_FOUND: i32 = -32601;
327→    pub const INVALID_PARAMS: i32 = -32602;
328→    pub const INTERNAL_ERROR: i32 = -32603;
329→}
