 17→//! Server implementations for system adapter JSON-RPC protocol.
 18→
 19→use crate::{
 20→    DatasetConfig, JsonRpcError, JsonRpcResponse, MetricsRequest, MetricsResponse, SetupRequest,
 21→    SetupResponse, TeardownRequest, TeardownResponse, error_codes, methods,
 22→};
 23→use async_trait::async_trait;
 24→use serde::de::DeserializeOwned;
 25→use std::collections::HashMap;
 26→use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
 27→use uuid::Uuid;
 28→
 29→/// Error type for server operations
 30→#[derive(Debug)]
 31→pub enum ServerError {
 32→    /// I/O error
 33→    Io(std::io::Error),
 34→    /// JSON serialization/deserialization error
 35→    Json(serde_json::Error),
 36→    /// Handler returned an error
 37→    Handler(String),
 38→}
 39→
 40→impl std::fmt::Display for ServerError {
 41→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 42→        match self {
 43→            Self::Io(e) => write!(f, "I/O error: {e}"),
 44→            Self::Json(e) => write!(f, "JSON error: {e}"),
 45→            Self::Handler(msg) => write!(f, "Handler error: {msg}"),
 46→        }
 47→    }
 48→}
 49→
 50→impl std::error::Error for ServerError {}
 51→
 52→impl From<std::io::Error> for ServerError {
 53→    fn from(e: std::io::Error) -> Self {
 54→        Self::Io(e)
 55→    }
 56→}
 57→
 58→impl From<serde_json::Error> for ServerError {
 59→    fn from(e: serde_json::Error) -> Self {
 60→        Self::Json(e)
 61→    }
 62→}
 63→
 64→/// Result type for server operations
 65→pub type Result<T> = std::result::Result<T, ServerError>;
 66→
 67→/// Handler trait for implementing system adapter logic
 68→///
 69→/// Implement this trait to define how your system adapter handles
 70→/// setup, teardown, and metrics requests.
 71→#[async_trait]
 72→pub trait Handler: Send + Sync {
 73→    /// Setup a benchmark run
 74→    async fn setup(
 75→        &mut self,
 76→        run_id: Uuid,
 77→        metadata: HashMap<String, serde_json::Value>,
 78→        datasets: HashMap<String, DatasetConfig>,
 79→    ) -> std::result::Result<SetupResponse, String>;
 80→
 81→    /// Teardown a benchmark run
 82→    async fn teardown(&mut self, run_id: Uuid) -> std::result::Result<TeardownResponse, String>;
 83→
 84→    /// Collect current metrics from the system under test
 85→    ///
 86→    /// Called periodically by spicebench when `--scrape-sut-metrics` is enabled.
 87→    /// Returns a snapshot of resource utilization and ingestion progress.
 88→    /// Default implementation returns empty metrics.
 89→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
 90→        let _ = run_id;
 91→        Ok(MetricsResponse::default())
 92→    }
 93→
 94→    /// List available RPC methods
 95→    ///
 96→    /// Override this if you want to add custom methods beyond the standard ones.
 97→    fn rpc_methods(&self) -> Vec<String> {
 98→        vec![
 99→            methods::SETUP.to_string(),
100→            methods::TEARDOWN.to_string(),
101→            methods::METRICS.to_string(),
102→            methods::RPC_METHODS.to_string(),
103→        ]
104→    }
105→}
106→
107→/// System adapter server
108→pub struct Server<H: Handler> {
109→    handler: H,
110→}
111→
112→impl<H: Handler> Server<H> {
113→    /// Create a new server with the given handler
114→    pub fn new(handler: H) -> Self {
115→        Self { handler }
116→    }
117→
118→    /// Run the server on stdio (reads from stdin, writes to stdout)
119→    pub async fn run_stdio(&mut self) -> Result<()> {
120→        let stdin = tokio::io::stdin();
121→        let mut stdout = tokio::io::stdout();
122→        let mut reader = BufReader::new(stdin);
123→        let mut line = String::new();
124→
125→        loop {
126→            line.clear();
127→            let bytes_read = reader.read_line(&mut line).await?;
128→
129→            if bytes_read == 0 {
130→                // EOF reached
131→                break;
132→            }
133→
134→            let response = self.handle_request(line.trim()).await;
135→            let response_json = serde_json::to_string(&response)?;
136→            stdout.write_all(response_json.as_bytes()).await?;
137→            stdout.write_all(b"\n").await?;
138→            stdout.flush().await?;
139→        }
140→
141→        Ok(())
142→    }
143→
144→    /// Handle a single JSON-RPC request
145→    async fn handle_request(&mut self, request_str: &str) -> serde_json::Value {
146→        // Parse the request
147→        let request: serde_json::Value = match serde_json::from_str(request_str) {
148→            Ok(req) => req,
149→            Err(e) => {
150→                return serde_json::to_value(JsonRpcResponse::<()>::error(
151→                    serde_json::Value::Null,
152→                    JsonRpcError::new(error_codes::PARSE_ERROR, format!("Parse error: {e}")),
153→                ))
154→                .unwrap_or(serde_json::json!({}));
155→            }
156→        };
157→
158→        let id = request
159→            .get("id")
160→            .cloned()
161→            .unwrap_or(serde_json::Value::Null);
162→        let method = match request.get("method").and_then(|v| v.as_str()) {
163→            Some(m) => m,
164→            None => {
165→                return serde_json::to_value(JsonRpcResponse::<()>::error(
166→                    id,
167→                    JsonRpcError::new(error_codes::INVALID_REQUEST, "Missing method"),
168→                ))
169→                .unwrap_or(serde_json::json!({}));
170→            }
171→        };
172→
173→        // Dispatch to appropriate handler
174→        let result = match method {
175→            methods::SETUP => self.handle_setup(&request, id.clone()).await,
176→            methods::TEARDOWN => self.handle_teardown(&request, id.clone()).await,
177→            methods::METRICS => self.handle_metrics(&request, id.clone()).await,
178→            methods::RPC_METHODS => self.handle_rpc_methods(id.clone()).await,
179→            _ => serde_json::to_value(JsonRpcResponse::<()>::error(
180→                id,
181→                JsonRpcError::new(error_codes::METHOD_NOT_FOUND, "Method not found"),
182→            ))
183→            .unwrap_or(serde_json::json!({})),
184→        };
185→
186→        result
187→    }
188→
189→    /// Parse and deserialize the `params` field from a JSON-RPC request.
190→    fn parse_params<T: DeserializeOwned>(
191→        request: &serde_json::Value,
192→        id: &serde_json::Value,
193→    ) -> std::result::Result<T, serde_json::Value> {
194→        let params = request.get("params").ok_or_else(|| {
195→            serde_json::to_value(JsonRpcResponse::<()>::error(
196→                id.clone(),
197→                JsonRpcError::new(error_codes::INVALID_PARAMS, "Missing params"),
198→            ))
199→            .unwrap_or(serde_json::json!({}))
200→        })?;
201→
202→        serde_json::from_value(params.clone()).map_err(|e| {
203→            serde_json::to_value(JsonRpcResponse::<()>::error(
204→                id.clone(),
205→                JsonRpcError::new(error_codes::INVALID_PARAMS, format!("Invalid params: {e}")),
206→            ))
207→            .unwrap_or(serde_json::json!({}))
208→        })
209→    }
210→
211→    /// Convert a handler result into a JSON-RPC response value.
212→    fn handler_response<T: serde::Serialize>(
213→        result: std::result::Result<T, String>,
214→        id: serde_json::Value,
215→    ) -> serde_json::Value {
216→        match result {
217→            Ok(response) => serde_json::to_value(JsonRpcResponse::success(id, response))
218→                .unwrap_or(serde_json::json!({})),
219→            Err(e) => serde_json::to_value(JsonRpcResponse::<()>::error(
220→                id,
221→                JsonRpcError::new(error_codes::INTERNAL_ERROR, e),
222→            ))
223→            .unwrap_or(serde_json::json!({})),
224→        }
225→    }
226→
227→    async fn handle_setup(
228→        &mut self,
229→        request: &serde_json::Value,
230→        id: serde_json::Value,
231→    ) -> serde_json::Value {
232→        let req: SetupRequest = match Self::parse_params(request, &id) {
233→            Ok(r) => r,
234→            Err(e) => return e,
235→        };
236→        Self::handler_response(
237→            self.handler
238→                .setup(req.run_id, req.metadata, req.datasets)
239→                .await,
240→            id,
241→        )
242→    }
243→
244→    async fn handle_teardown(
245→        &mut self,
246→        request: &serde_json::Value,
247→        id: serde_json::Value,
248→    ) -> serde_json::Value {
249→        let req: TeardownRequest = match Self::parse_params(request, &id) {
250→            Ok(r) => r,
251→            Err(e) => return e,
252→        };
253→        Self::handler_response(self.handler.teardown(req.run_id).await, id)
254→    }
255→
256→    async fn handle_metrics(
257→        &mut self,
258→        request: &serde_json::Value,
259→        id: serde_json::Value,
260→    ) -> serde_json::Value {
261→        let req: MetricsRequest = match Self::parse_params(request, &id) {
262→            Ok(r) => r,
263→            Err(e) => return e,
264→        };
265→        Self::handler_response(self.handler.metrics(req.run_id).await, id)
266→    }
267→
268→    async fn handle_rpc_methods(&mut self, id: serde_json::Value) -> serde_json::Value {
269→        let methods = self.handler.rpc_methods();
