 17→//! Client implementations for system adapter JSON-RPC communication.
 18→
 19→use crate::{JsonRpcError, JsonRpcRequest, JsonRpcResponse, methods};
 20→use serde::{Serialize, de::DeserializeOwned};
 21→use std::collections::HashMap;
 22→use tokio::{
 23→    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
 24→    process::{Child, ChildStdin, ChildStdout, Command},
 25→};
 26→
 27→/// Result type for client operations
 28→pub type Result<T> = std::result::Result<T, ClientError>;
 29→
 30→/// Errors that can occur during client operations
 31→#[derive(Debug)]
 32→pub enum ClientError {
 33→    /// JSON-RPC error returned by the server
 34→    JsonRpc(JsonRpcError),
 35→    /// I/O error during communication
 36→    Io(std::io::Error),
 37→    /// JSON serialization/deserialization error
 38→    Json(serde_json::Error),
 39→    /// HTTP transport error
 40→    #[cfg(feature = "client")]
 41→    Http(reqwest::Error),
 42→    /// Invalid response format
 43→    InvalidResponse(String),
 44→    /// Transport-specific error
 45→    Transport(String),
 46→}
 47→
 48→impl std::fmt::Display for ClientError {
 49→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 50→        match self {
 51→            Self::JsonRpc(e) => write!(f, "JSON-RPC error: {}", e.message),
 52→            Self::Io(e) => write!(f, "I/O error: {e}"),
 53→            Self::Json(e) => write!(f, "JSON error: {e}"),
 54→            #[cfg(feature = "client")]
 55→            Self::Http(e) => write!(f, "HTTP error: {e}"),
 56→            Self::InvalidResponse(msg) => write!(f, "Invalid response: {msg}"),
 57→            Self::Transport(msg) => write!(f, "Transport error: {msg}"),
 58→        }
 59→    }
 60→}
 61→
 62→impl std::error::Error for ClientError {}
 63→
 64→impl From<std::io::Error> for ClientError {
 65→    fn from(e: std::io::Error) -> Self {
 66→        Self::Io(e)
 67→    }
 68→}
 69→
 70→impl From<serde_json::Error> for ClientError {
 71→    fn from(e: serde_json::Error) -> Self {
 72→        Self::Json(e)
 73→    }
 74→}
 75→
 76→#[cfg(feature = "client")]
 77→impl From<reqwest::Error> for ClientError {
 78→    fn from(e: reqwest::Error) -> Self {
 79→        Self::Http(e)
 80→    }
 81→}
 82→
 83→/// System adapter client for JSON-RPC communication
 84→pub enum Client {
 85→    /// Stdio transport - communicate via stdin/stdout with a child process
 86→    Stdio {
 87→        _child: Box<Child>,
 88→        stdin: ChildStdin,
 89→        stdout: BufReader<ChildStdout>,
 90→    },
 91→    /// HTTP transport - communicate via HTTP POST requests
 92→    #[cfg(feature = "client")]
 93→    Http {
 94→        client: reqwest::Client,
 95→        endpoint: String,
 96→    },
 97→}
 98→
 99→impl Client {
100→    /// Create a client using stdio transport by spawning a command
101→    pub fn stdio(
102→        command: impl AsRef<str>,
103→        args: Vec<String>,
104→        env: HashMap<String, String>,
105→    ) -> Result<Self> {
106→        let command_str = command.as_ref();
107→        let mut cmd = Command::new(command_str);
108→
109→        cmd.args(args);
110→        for (key, value) in env {
111→            cmd.env(key, value);
112→        }
113→
114→        cmd.stdin(std::process::Stdio::piped())
115→            .stdout(std::process::Stdio::piped())
116→            .stderr(std::process::Stdio::inherit());
117→
118→        let mut child = cmd.spawn().map_err(|e| {
119→            ClientError::Transport(format!(
120→                "Failed to start stdio command '{command_str}': {e}"
121→            ))
122→        })?;
123→
124→        let stdin = child
125→            .stdin
126→            .take()
127→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdin".to_string()))?;
128→        let stdout = child
129→            .stdout
130→            .take()
131→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdout".to_string()))?;
132→
133→        Ok(Self::Stdio {
134→            _child: Box::new(child),
135→            stdin,
136→            stdout: BufReader::new(stdout),
137→        })
138→    }
139→
140→    /// Create a client using HTTP transport
141→    #[cfg(feature = "client")]
142→    pub fn http(endpoint: impl Into<String>) -> Self {
143→        Self::Http {
144→            client: reqwest::Client::new(),
145→            endpoint: endpoint.into(),
146→        }
147→    }
148→
149→    /// Get the transport name
150→    pub fn transport_name(&self) -> &'static str {
151→        match self {
152→            Self::Stdio { .. } => "stdio",
153→            #[cfg(feature = "client")]
154→            Self::Http { .. } => "http",
155→        }
156→    }
157→
158→    /// Query available RPC methods from the server
159→    pub async fn rpc_methods(&mut self) -> Result<Vec<String>> {
160→        let request = JsonRpcRequest::new(1, methods::RPC_METHODS, serde_json::json!({}));
161→        let response: JsonRpcResponse<serde_json::Value> = self.call_typed(request).await?;
162→
163→        let methods = response
164→            .result
165→            .as_ref()
166→            .and_then(|v| v.get("methods"))
167→            .and_then(|v| v.as_array())
168→            .ok_or_else(|| {
169→                ClientError::InvalidResponse("Response missing result.methods array".to_string())
170→            })?
171→            .iter()
172→            .filter_map(|v| v.as_str().map(ToString::to_string))
173→            .collect();
174→
175→        Ok(methods)
176→    }
177→
178→    /// Setup a benchmark run
179→    pub async fn setup(
180→        &mut self,
181→        run_id: uuid::Uuid,
182→        metadata: std::collections::HashMap<String, serde_json::Value>,
183→        datasets: std::collections::HashMap<String, crate::DatasetConfig>,
184→    ) -> Result<crate::SetupResponse> {
185→        let request = crate::SetupRequest {
186→            run_id,
187→            metadata,
188→            datasets,
189→        };
190→        let rpc_request = JsonRpcRequest::new(1, crate::methods::SETUP, request);
191→        let response = self.call_typed(rpc_request).await?;
192→        response
193→            .result
194→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
195→    }
196→
197→    /// Teardown a benchmark run
198→    pub async fn teardown(&mut self, run_id: uuid::Uuid) -> Result<crate::TeardownResponse> {
199→        let request = crate::TeardownRequest { run_id };
200→        let rpc_request = JsonRpcRequest::new(1, crate::methods::TEARDOWN, request);
201→        let response = self.call_typed(rpc_request).await?;
202→        response
203→            .result
204→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
205→    }
206→
207→    /// Collect current metrics from the system under test
208→    pub async fn metrics(&mut self, run_id: uuid::Uuid) -> Result<crate::MetricsResponse> {
209→        let request = crate::MetricsRequest { run_id };
210→        let rpc_request = JsonRpcRequest::new(1, crate::methods::METRICS, request);
211→        let response = self.call_typed(rpc_request).await?;
212→        response
213→            .result
214→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
215→    }
216→
217→    /// Make a typed JSON-RPC call with request and response types
218→    async fn call_typed<Req: Serialize, Resp: DeserializeOwned>(
219→        &mut self,
220→        request: JsonRpcRequest<Req>,
221→    ) -> Result<JsonRpcResponse<Resp>> {
222→        let request_value = serde_json::to_value(request)?;
223→        let response_value = self.call_raw(request_value).await?;
224→        let response: JsonRpcResponse<Resp> = serde_json::from_value(response_value)?;
225→        Ok(response)
226→    }
227→
228→    /// Make a raw JSON-RPC call with serde_json::Value
229→    async fn call_raw(&mut self, request: serde_json::Value) -> Result<serde_json::Value> {
230→        match self {
231→            Self::Stdio {
232→                _child: _,
233→                stdin,
234→                stdout,
235→            } => {
236→                let payload = serde_json::to_string(&request)?;
237→                stdin.write_all(payload.as_bytes()).await?;
238→                stdin.write_all(b"\n").await?;
239→                stdin.flush().await?;
240→
241→                let mut line = String::new();
242→                let read = stdout.read_line(&mut line).await?;
243→                if read == 0 {
244→                    return Err(ClientError::Transport(
245→                        "Stdio process closed stdout before responding".to_string(),
246→                    ));
247→                }
248→
249→                let response: serde_json::Value = serde_json::from_str(line.trim_end())?;
250→                if let Some(error) = response.get("error") {
251→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
252→                    return Err(ClientError::JsonRpc(error));
253→                }
254→                Ok(response)
255→            }
256→            #[cfg(feature = "client")]
257→            Self::Http { client, endpoint } => {
258→                let response = client
259→                    .post(endpoint.as_str())
260→                    .json(&request)
261→                    .send()
262→                    .await
263→                    .map_err(|e| {
264→                        ClientError::Transport(format!("Failed to POST to {endpoint}: {e}"))
265→                    })?;
266→
267→                let status = response.status();
268→                let value: serde_json::Value = response.json().await.map_err(|e| {
269→                    ClientError::Transport(format!(
270→                        "Failed to parse response body (status {status}): {e}"
271→                    ))
272→                })?;
273→
274→                if let Some(error) = value.get("error") {
275→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
276→                    return Err(ClientError::JsonRpc(error));
277→                }
278→                Ok(value)
279→            }
280→        }
281→    }
282→}
283→
284→/// Builder for creating a `Client` with various configuration options
285→pub struct ClientBuilder {
286→    transport: TransportConfig,
287→}
288→
289→enum TransportConfig {
290→    Stdio {
291→        command: String,
292→        args: Vec<String>,
293→        env: HashMap<String, String>,
294→    },
295→    #[cfg(feature = "client")]
296→    Http { endpoint: String },
297→}
298→
299→impl ClientBuilder {
300→    /// Create a builder for stdio transport
301→    pub fn stdio(command: impl Into<String>) -> Self {
302→        Self {
303→            transport: TransportConfig::Stdio {
304→                command: command.into(),
305→                args: Vec::new(),
306→                env: HashMap::new(),
307→            },
308→        }
309→    }
310→
311→    /// Create a builder for HTTP transport
312→    #[cfg(feature = "client")]
313→    pub fn http(endpoint: impl Into<String>) -> Self {
314→        Self {
315→            transport: TransportConfig::Http {
316→                endpoint: endpoint.into(),
317→            },
318→        }
319→    }
320→
321→    /// Add command-line arguments (stdio only)
322→    pub fn with_args(mut self, args: Vec<String>) -> Self {
323→        if let TransportConfig::Stdio {
324→            args: ref mut a, ..
325→        } = self.transport
326→        {
327→            *a = args;
328→        }
329→        self
330→    }
331→
332→    /// Add environment variables (stdio only)
333→    pub fn with_env(mut self, env: HashMap<String, String>) -> Self {
334→        if let TransportConfig::Stdio { env: ref mut e, .. } = self.transport {
335→            *e = env;
336→        }
337→        self
338→    }
339→
340→    /// Build the client
341→    pub fn build(self) -> Result<Client> {
342→        match self.transport {
343→            TransportConfig::Stdio { command, args, env } => Client::stdio(command, args, env),
344→            #[cfg(feature = "client")]
345→            TransportConfig::Http { endpoint } => Ok(Client::http(endpoint)),
346→        }
347→    }
348→}
